<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {launchApi,defaults,rows,stateNames,actionNames,attachmentList,uploadAttachment,downloadAttachment,type Workspace,type Document,type Row,type Value,type LaunchAttachment} from '@/api/launch'
import {candidatesApi} from '@/api/candidates'
import {session} from '@/state/session'
import {confirmAction} from '@/state/uiConfirmation'
import {candidateTabs,candidateScore,issueTab,riskLabels,safeLink,formatDate} from '@/utils/candidatePresentation'
import {sections,riskNames,type Field,type Section} from './schema'
import CandidateFields from './CandidateFields.vue'
import AccessDialog from '@/components/AccessDialog.vue'
import ListPagination from '@/components/ListPagination.vue'
const props=defineProps<{candidateId:string}>(),emit=defineEmits<{close:[];changed:[]}>(),api=launchApi(false)
const snapshot=ref<Document>()
const dialog=ref<HTMLDialogElement>(),workspace=ref<Workspace>(),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),tab=ref('overview'),legacy=ref<Record<string,unknown>>({})
const doc=computed(()=>defaults(workspace.value?.document??{})),writer=computed(()=>session.canAccess(['selection.write'])),reviewer=computed(()=>session.canAccess(['selection.review'])),editable=computed(()=>writer.value&&['NEW','EVALUATING','RETURNED'].includes(workspace.value?.state??''))
const editor=ref<{title:string;fields:Field[];key?:string|undefined;id?:Value|undefined}>(),draft=ref<Row>({}),initial=ref(''),editError=ref(''),action=ref(''),reason=ref(''),selfConfirmed=ref(false)
const jobReason=ref(''),lastJobKey=ref(''),awaitingJob=ref(false)
let pendingChecks=0
const dirty=computed(()=>!!editor.value&&JSON.stringify(draft.value)!==initial.value),attachments=ref<LaunchAttachment[]>([]),observation=ref<Record<string,unknown>>({}),job=ref(''),historyPage=ref(1),historySize=ref(10)
let previous:HTMLElement|null=null,poll:ReturnType<typeof setTimeout>|undefined,alive=true
const history=computed(()=>[...(workspace.value?.history??[])].sort((a,b)=>b.version-a.version)),historyRows=computed(()=>history.value.slice((historyPage.value-1)*historySize.value,historyPage.value*historySize.value))
const currentSections=computed(()=>sections.filter(s=>tab.value==='needs'?['needs','requirements'].includes(s.key):s.key===tab.value))
const groupedIssues=computed(()=>candidateTabs.map(t=>({...t,issues:(workspace.value?.issues??[]).filter(i=>issueTab(i)===t.key)})).filter(t=>t.issues.length))
const actions=computed(()=>{if(!workspace.value||!writer.value)return [];const s=workspace.value.state,result:string[]=[];if(s==='NEW')result.push('START');if(['EVALUATING','RETURNED'].includes(s))result.push('SUBMIT');if(s==='REVIEW'){result.push('WITHDRAW');if(reviewer.value)result.push('APPROVE','RETURN')}if(s==='REJECTED')result.push('REOPEN');if(reviewer.value&&!['APPROVED','REJECTED'].includes(s))result.push('REJECT');return result})
const fields=(section:Section)=> (section.fields??[]).filter(f=>!['buyer','startDate','endDate','legacyNotes','changeReason','budget'].includes(f.key))
function columns(section:Section,source:Document=doc.value){return (section.columns??[]).filter(f=>section.key!=='requirements'||!['owner','result','testedVersion','evidence','disposition'].includes(f.key)).map(f=>f.key==='needId'?{...f,type:'select' as const,options:rows(source,'needs').map(r=>[String(r.id),String(r.name||r.pain||'未命名需求')])}:f)}
function tableColumns(section:Section){const keys:Record<string,string[]>={risk:['type','scope','investigator','date','conclusion'],requirements:['needId','proposal','priority','standard'],needs:['name','pain','nature','validation']};return columns(section).filter(f=>!keys[section.key]||keys[section.key]!.includes(f.key))}
function display(field:Field,value:unknown){if(value==null||value==='')return '—';if(['commission','advertising','loss'].includes(field.key))return `${Number(value)*100}%`;return field.options?.find(o=>o[0]===String(value))?.[1]??String(value)}
function accept(w:Workspace){workspace.value=w;emit('changed')}
async function load(){loading.value=true;error.value='';try{const result=await api.get(props.candidateId);legacy.value=result.legacy;if('version'in result.workspace)workspace.value=result.workspace as Workspace;else workspace.value=undefined}catch(e){error.value=message(e)}finally{loading.value=false}}
const message=(e:unknown)=>e instanceof Error?e.message:'操作失败，请重试'
async function initialize(){busy.value=true;try{accept(await api.initialize(props.candidateId))}catch(e){error.value=message(e)}finally{busy.value=false}}
function edit(section:Section,row?:Row,basic=false){editError.value='';const isRows=!!section.rows&&!basic;editor.value={title:`${row?'编辑':isRows?'新增':'编辑'}${section.title}`,fields:isRows?columns(section):fields(section).filter(f=>f.key!=='asin'),key:isRows?section.rows:undefined,id:row?.id};draft.value=isRows?{id:crypto.randomUUID(),...row}:Object.fromEntries(fields(section).map(f=>[f.key,doc.value[f.key] as Value??'']));initial.value=JSON.stringify(draft.value)}
async function closeEditor(){if(!busy.value&&(!dirty.value||await confirmAction('放弃未保存的修改？')))editor.value=undefined}
async function saveEditor(){if(!editor.value||!workspace.value)return;busy.value=true;editError.value='';try{const next=structuredClone(doc.value),edit=editor.value;if(edit.key){const list=rows(next,edit.key);next[edit.key]=edit.id?list.map(r=>r.id===edit.id?{...r,...draft.value}:r):[...list,{...draft.value}]}else Object.assign(next,draft.value);accept(await api.save(props.candidateId,workspace.value.version,next));editor.value=undefined;notice.value='资料已保存'}catch(e){editError.value=message(e)}finally{busy.value=false}}
async function remove(section:Section,row:Row){if(section.rows==='needs'&&rows(doc.value,'requirements').some(r=>r.needId===row.id)){error.value='该需求已关联改进建议，请先修改关联后再移除。';return}if(!workspace.value||!await confirmAction('移除此条评估明细？'))return;busy.value=true;try{accept(await api.save(props.candidateId,workspace.value.version,{...doc.value,[section.rows!]:rows(doc.value,section.rows!).filter(r=>r.id!==row.id)}))}catch(e){error.value=message(e)}finally{busy.value=false}}
function ask(value:string){error.value='';if(value==='SUBMIT'&&workspace.value?.issues.length){tab.value='overview';error.value='请先完成下方待补充事项，再提交审核。';return}editError.value='';action.value=value;reason.value='';selfConfirmed.value=false}
async function runAction(){if(!workspace.value)return;busy.value=true;editError.value='';try{accept(await api.action(props.candidateId,workspace.value.version,action.value,reason.value,selfConfirmed.value));action.value='';notice.value='操作已完成'}catch(e){editError.value=message(e)}finally{busy.value=false}}
async function readObservation(){try{const data=await candidatesApi.observation(props.candidateId);if(!alive)return;observation.value=data.observation??{};const key=String(data.job?.[0]?.created_at??'');if(awaitingJob.value&&key===lastJobKey.value&&pendingChecks++<24){poll=setTimeout(()=>void readObservation(),5000);return}awaitingJob.value=false;lastJobKey.value=key;jobReason.value=String(data.job?.[0]?.reason??'');job.value=String(data.job?.[0]?.status??'');if(['QUEUED','RUNNING','PENDING','RETRY'].includes(job.value)){clearTimeout(poll);poll=setTimeout(()=>void readObservation(),5000)}}catch(e){if(alive)error.value=message(e)}}
async function collect(){busy.value=true;try{await candidatesApi.collect(props.candidateId);notice.value='已提交采集任务';awaitingJob.value=true;pendingChecks=0;job.value='QUEUED';clearTimeout(poll);poll=setTimeout(()=>void readObservation(),3000)}catch(e){error.value=message(e)}finally{busy.value=false}}
async function adopt(){if(!workspace.value||!await confirmAction('将最新采集的参考价格、评分、图片和上架日期填入评估？已有对应参考数据将被替换。'))return;busy.value=true;try{const next={...doc.value};for(const [from,to]of Object.entries({title:'referenceTitle',imageUrl:'imageUrl',price:'referencePrice',rating:'rating',ratingCount:'ratingCount',listedAt:'availableDate',brand:'referenceBrand'})){const v=observation.value[from];if(typeof v==='string'||typeof v==='number')next[to]=v}accept(await api.save(props.candidateId,workspace.value.version,next));notice.value='参考数据已采纳'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function files(){try{attachments.value=await attachmentList('CANDIDATE',props.candidateId)}catch(e){error.value=message(e)}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;try{await uploadAttachment('CANDIDATE',props.candidateId,file);await files();notice.value='附件已上传，可在评估依据中引用附件名称。'}catch(e){error.value=message(e)}finally{input.value='';busy.value=false}}
async function download(file:LaunchAttachment){try{await downloadAttachment('CANDIDATE',props.candidateId,file)}catch(e){error.value=message(e)}}
async function guard(){return !busy.value&&(!dirty.value||await confirmAction('放弃未保存的评估修改？'))}
async function close(){if(await guard())emit('close')}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
watch(tab,v=>{if(v==='market')void readObservation();if(v==='evidence')void files()})
onMounted(()=>{previous=document.activeElement as HTMLElement;dialog.value?.showModal();void load();window.addEventListener('beforeunload',unload)})
onBeforeUnmount(()=>{alive=false;clearTimeout(poll);window.removeEventListener('beforeunload',unload);dialog.value?.close();previous?.focus({preventScroll:true})})
</script>
<template>
  <!-- eslint-disable vue/max-attributes-per-line, vue/singleline-html-element-content-newline -->
  <dialog ref="dialog" class="candidate-detail candidate-ui" aria-label="候选评估详情" @cancel.prevent="close">
    <header class="candidate-detail-header"><div><h2>{{ doc.name||'候选评估' }}</h2><small>{{ doc.asin||'产品机会评估' }} <span class="candidate-badge" :data-state="workspace?.state">{{ stateNames[workspace?.state??''] }}</span></small></div><button aria-label="关闭详情" :disabled="busy" @click="close">×</button></header>
    <nav class="candidate-detail-tabs" aria-label="评估内容"><button v-for="t in candidateTabs" :key="t.key" :aria-current="tab===t.key?'page':undefined" @click="tab=t.key">{{ t.title }}</button></nav>
    <main class="candidate-detail-body">
      <p v-if="error" role="alert" class="data-state--error">{{ error }} <button v-if="!workspace" @click="load">重试</button></p><p v-if="notice" role="status" class="candidate-notice">{{ notice }}</p>
      <p v-if="loading">正在加载评估资料…</p>
      <div v-else-if="!workspace" class="data-state"><h3>启用结构化评估</h3><p>保留原候选信息，补充市场、需求、成本和风险调查后送审。</p><button v-if="writer" :disabled="busy" class="candidate-primary" @click="initialize">开始完善评估</button></div>
      <template v-else>
        <details v-if="workspace.issues.some(i=>issueTab(i)===tab)&&!['APPROVED','REJECTED'].includes(workspace.state)" class="candidate-issues"><summary>本模块待补充事项（{{ workspace.issues.filter(i=>issueTab(i)===tab).length }}）</summary><ul><li v-for="(issue,index) in workspace.issues.filter(i=>issueTab(i)===tab)" :key="index">{{ issue.replace('commission','佣金率').replace('advertising','广告率').replace('loss','售后损耗率') }}</li></ul></details>
        <template v-if="tab==='overview'">
          <div class="candidate-metrics"><article><span>评估得分</span><strong>{{ candidateScore(doc)??'待完善' }}<small v-if="candidateScore(doc)!=null"> / 100</small></strong></article><article><span>目标售价 · USD</span><strong>{{ doc.price??'—' }}</strong></article><article><span>单件贡献 · USD</span><strong>{{ workspace.calculation?.profit?.toFixed(2)??'待试算' }}</strong></article><article><span>风险复核</span><strong>{{ workspace.riskReview.valid?'已复核':'待复核' }}</strong></article></div>
          <section v-if="!['APPROVED','REJECTED'].includes(workspace.state)" class="candidate-checklist"><h3>评估待办 <small>{{ workspace.issues.length }} 项待完善</small></h3><p>按模块补充依据，完成后提交审核。审核通过将生成新品开发草稿。</p><div v-if="groupedIssues.length" class="candidate-check-grid"><button v-for="group in groupedIssues" :key="group.key" @click="tab=group.key"><b>{{ group.title }} <span>{{ group.issues.length }}</span></b><small>{{ group.issues[0] }}</small></button></div><p v-else class="candidate-notice">资料检查已通过，可以提交审核。</p></section>
        </template>
        <template v-if="tab==='market'"><section class="candidate-section"><div class="candidate-section-heading"><h3>亚马逊参考数据</h3><div><button @click="readObservation">读取采集结果</button><button v-if="editable&&doc.asin" :disabled="busy||['QUEUED','RUNNING','PENDING','RETRY'].includes(job)" @click="collect">{{ ['QUEUED','RUNNING','PENDING','RETRY'].includes(job)?'正在采集…':'采集最新数据' }}</button><button v-if="editable&&Object.keys(observation).length" :disabled="busy" @click="adopt">采纳参考数据</button></div></div><p class="candidate-hint">采集结果与人工评估分开保存，核对后采纳。销量未知时填写无数据原因与验证依据。</p><dl class="candidate-facts"><div v-for="(label,key) in {title:'参考标题',price:'参考价格',rating:'星级',ratingCount:'评分数',listedAt:'上架日期'}" :key="key"><dt>{{ label }}</dt><dd>{{ observation[key]??'尚无数据' }}</dd></div></dl><p v-if="job">采集状态：{{ ({QUEUED:'排队中',PENDING:'等待中',RUNNING:'采集中',SUCCEEDED:'已完成',SUCCESS:'已完成',RETRY:'等待自动重试',PARTIAL:'数据不完整',CANCELLED:'已取消',FAILED:'失败，请稍后重试'} as Record<string,string>)[job]??job }}<span v-if="jobReason"> · {{ jobReason }}</span></p></section></template>
        <section v-if="tab==='cost'" class="candidate-metrics"><article v-for="(label,key) in {profit:'单件贡献 USD',margin:'贡献率',breakEven:'盈亏平衡售价 USD',monthlyProfit:'预计月贡献 USD'}" :key="key"><span>{{ label }}</span><strong>{{ workspace.calculation?.[key]!=null?(key==='margin'?(Number(workspace.calculation[key])*100).toFixed(1)+'%':Number(workspace.calculation[key]).toFixed(2)):'待完善成本' }}</strong></article></section>
        <section v-if="tab==='risk'" class="candidate-checklist"><div class="candidate-section-heading"><h3>{{ workspace.riskReview.valid?'风险调查已复核':'风险调查待复核' }}</h3><button v-if="editable&&reviewer" :disabled="busy" @click="ask('REVIEW_RISK')">复核风险调查</button></div><p>方案或调查内容发生变化后，需要重新复核。</p><p v-if="workspace.riskReview.actor">{{ workspace.riskReview.actor }} · {{ formatDate(workspace.riskReview.date) }} · {{ workspace.riskReview.reason }}</p></section>
        <section v-for="section in currentSections" :key="section.key" class="candidate-section"><div class="candidate-section-heading"><h3>{{ section.title }}</h3><div v-if="editable"><button v-if="fields(section).length" :disabled="busy" @click="edit(section,undefined,true)">编辑资料</button><button v-if="section.rows&&section.key!=='criteria'" :disabled="busy" @click="edit(section)">＋ 新增明细</button></div></div><p class="candidate-hint">{{ section.description }}</p><dl v-if="fields(section).length" class="candidate-facts"><div v-for="field in fields(section)" :key="field.key" :class="{'candidate-field-wide':field.type==='textarea'}"><dt>{{ field.label.replace("（0–1）","（%）") }}</dt><dd><a v-if="['sourceUrl','imageUrl'].includes(field.key)&&safeLink(doc[field.key])" :href="safeLink(doc[field.key])" target="_blank" rel="noopener noreferrer">查看链接 ↗</a><template v-else>{{ display(field,doc[field.key]) }}</template></dd></div></dl><div v-if="section.rows" class="candidate-row-table"><table><thead><tr><th v-for="field in tableColumns(section)" :key="field.key">{{ field.label }}</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows(doc,section.rows)" :key="String(row.id)"><td v-for="field in tableColumns(section)" :key="field.key">{{ field.key==='type'?riskNames[String(row[field.key])]??row[field.key]:field.key==='conclusion'?riskLabels[String(row[field.key])]??row[field.key]:display(field,row[field.key]) }}</td><td><button :disabled="busy" @click="edit(section,row)">{{ editable?'编辑':'查看' }}</button><button v-if="editable&&section.key!=='criteria'" :disabled="busy" @click="remove(section,row)">移除</button></td></tr><tr v-if="!rows(doc,section.rows).length"><td :colspan="tableColumns(section).length+1" class="data-state">暂无明细{{ editable?'，点击“新增明细”开始完善。':'。' }}</td></tr></tbody></table></div></section>
        <section v-if="tab==='evidence'" class="candidate-section"><div class="candidate-section-heading"><h3>附件资料</h3><label v-if="editable" class="candidate-upload">上传附件<input type="file" :disabled="busy" @change="upload"></label></div><p v-if="!attachments.length" class="candidate-hint">暂无附件，可上传调查报告、样品图片或客户需求证据。</p><div v-for="file in attachments" :key="file.id" class="candidate-file"><button @click="download(file)">{{ file.name }}</button><small>{{ Math.ceil(file.size/1024) }} KB</small></div><p v-if="doc.legacyNotes">历史记录：{{ doc.legacyNotes }}</p></section>
        <section v-if="tab==='history'" class="candidate-section"><h3>操作记录 <small>{{ history.length }} 条</small></h3><div v-for="entry in historyRows" :key="entry.version" class="candidate-history"><div><b>{{ actionNames[entry.action]??entry.action }}</b><span>{{ entry.actor }} · {{ formatDate(entry.date) }} · 版本 {{ entry.version }}</span></div><p>{{ entry.reason||'—' }}</p><small>状态：{{ stateNames[entry.snapshot.state]??entry.snapshot.state }}</small> <button @click="snapshot=entry.snapshot.document">查看版本资料</button></div><p v-if="!history.length">暂无操作记录</p></section>
      </template>
    </main>
    <footer class="candidate-detail-footer"><ListPagination v-if="tab==='history'" :page="historyPage" :page-size="historySize" :total="history.length" @update:page="historyPage=$event" @update:page-size="historySize=$event;historyPage=1" /><template v-else><span>{{ editable?'资料按模块保存，完成评估后提交审核。':'当前状态只读，评估资料与审核记录已保留。' }}</span><div><RouterLink v-if="workspace?.state==='APPROVED'&&session.canAccess(['development.read'])" :to="`/product-development/${candidateId}`">进入新品开发 ↗</RouterLink><button v-for="(a,index) in actions" :key="a" :class="{'candidate-primary':index===0||a==='APPROVE'}" :disabled="busy" @click="ask(a)">{{ actionNames[a] }}</button></div></template></footer>
  </dialog>
  <AccessDialog v-if="snapshot" title="历史版本资料（只读）" wide @close="snapshot=undefined"><section v-for="section in sections.filter(s=>candidateTabs.some(t=>t.key===s.key)||s.key==='requirements')" :key="section.key" class="candidate-section"><h3>{{ section.title }}</h3><dl class="candidate-facts"><div v-for="field in fields(section)" :key="field.key"><dt>{{ field.label.replace("（0–1）","（%）") }}</dt><dd>{{ display(field,snapshot[field.key]) }}</dd></div></dl><div v-if="section.rows"><dl v-for="(row,index) in rows(snapshot,section.rows)" :key="index" class="candidate-facts"><div v-for="field in columns(section,snapshot)" :key="field.key"><dt>{{ field.label.replace("（0–1）","（%）") }}</dt><dd>{{ display(field,row[field.key]) }}</dd></div></dl></div></section></AccessDialog>
  <AccessDialog v-if="editor" :title="editor.title" :busy="busy" :dirty="dirty" wide @close="editor=undefined"><form id="candidate-edit" @submit.prevent="saveEditor"><p v-if="editError" role="alert" class="data-state--error">{{ editError }}</p><CandidateFields :fields="editor.fields" :model="draft" :disabled="!editable||busy" @change="(key,value)=>draft[key]=value" /></form><template #footer><button :disabled="busy" @click="closeEditor">{{ editable?'取消':'关闭' }}</button><button v-if="editable" class="candidate-primary" form="candidate-edit" :disabled="busy||!dirty">{{ busy?'保存中…':'保存' }}</button></template></AccessDialog>
  <AccessDialog v-if="action" :title="actionNames[action]??action" :busy="busy" @close="action=''"><form id="candidate-action" class="access-form" @submit.prevent="runAction"><p v-if="editError" role="alert" class="data-state--error">{{ editError }}</p><p v-if="action==='APPROVE'">通过后将锁定评估方案，并生成关联的新品开发草稿。</p><label>操作说明<textarea v-model="reason" :required="!['START','SUBMIT','WITHDRAW'].includes(action)" rows="3" /></label><label v-if="action==='APPROVE'"><input v-model="selfConfirmed" type="checkbox">若本人提交，确认执行自审并保留审计记录</label></form><template #footer><button :disabled="busy" @click="action=''">取消</button><button class="candidate-primary" form="candidate-action" :disabled="busy">{{ busy?'处理中…':'确认'+actionNames[action] }}</button></template></AccessDialog>
</template>
